def query_model(self, model, condition=None, offset=None, limit=None,
                    group_by=None, having=None, order_by=None, fields=None):
        """
        Query all records with limit and offset, it's used for pagination query.
        """
        if self._query is not None:
            query = self._query
        else:
            query = self.get_select()

        if condition is not None:
            if isinstance(query, Result):
                query = query.filter(condition)
            else:
                query = query.where(condition)
        if self.pagination:
            if offset is not None:
                query = query.offset(int(offset))
            if limit is not None:
                query = query.limit(int(limit))
        if order_by is not None:
            if isinstance(order_by, (tuple, list)):
                for order in order_by:
                    query = query.order_by(order)
            else:
                query = query.order_by(order_by)
        if group_by is not None:
            if isinstance(group_by, (tuple, list)):
                query = query.group_by(*group_by)
            else:
                query = query.group_by(group_by)
            if having is not None:
                query = query.having(having)
        return query

def _get_client_secret(client, service_id):
    """
    Get client secret for service
    :param client: Accounts Service API Client
    :param service_id: Service ID
    :return: Client secret (if available)
    """
    try:
        response = client.accounts.services[service_id].secrets.get()
    except httpclient.HTTPError as exc:
        if exc.code == 404:
            # If error is a 404 then this means the service_id is not recognised. Raise this error immediately
            msg = ('Service {} cannot be found.'.format(service_id))
            raise click.ClickException(click.style(msg, fg='red'))
        else:
            raise exc

    client_secrets = response['data']
    if client_secrets:
        return client_secrets[0]
    return None

def visit_call(self, node):
        """return an astroid.Call node as string"""
        expr_str = self._precedence_parens(node, node.func)
        args = [arg.accept(self) for arg in node.args]
        if node.keywords:
            keywords = [kwarg.accept(self) for kwarg in node.keywords]
        else:
            keywords = []

        args.extend(keywords)
        return "%s(%s)" % (expr_str, ", ".join(args))

def calcTotal( self, values ):
        """
        Calculates the total for the given values.  For Datetime/Time objects,
        this will be seconds from minimum to maximum - defaulting to 1 second.
        For Date objects, this will be days from minimum to maximum, defaulting
        to 1 day.  For Number objects, this will be the sum of the list.  For
        Custom objects, a -1 value is returned.

        :param      values | [<variant>, ..]

        :return     <int>
        """
        rtype = self.rulerType()

        if ( not values ):
            return 0

        if ( rtype == XChartRuler.Type.Number ):
            return sum(values)

        elif ( rtype == XChartRuler.Type.Date ):
            values.sort()
            days = values[0].daysTo(values[-1])
            return max(1, days)

        elif ( rtype in (XChartRuler.Type.Datetime, XChartRuler.Type.Time) ):
            values.sort()
            secs = values[0].secsTo(values[-1])
            return max(1, secs)

        return -1

