def rss_parse(self, response):
        """
        Extracts all article links and initiates crawling them.

        :param obj response: The scrapy response
        """
        for item in response.xpath('//item'):
            for url in item.xpath('link/text()').extract():
                yield scrapy.Request(url, lambda resp: self.article_parse(
                    resp, item.xpath('title/text()').extract()[0]))

def find(self, *params):
        """按照简单、一般、特殊的顺序寻找新闻发布时间

        Keyword *params:
        params                  -- 可以接收多个含有时间的文本，str类型
        """

        for string in params:
            self.easy_time_extrator(string)
            if self.check_time_extrator():
                log('debug', '通过简单模式找到时间信息')
                return self.check_time_extrator()

        for string in params:
            self.common_time_extrator(string)
            if self.check_time_extrator():
                log('debug', '通过一般模式找到时间信息')
                return self.check_time_extrator()

        for string in params:
            self.special_time_extrator(string)
            if self.check_time_extrator():
                log('debug', '通过特殊模式找到时间信息')
                return self.check_time_extrator()

def adjoint(self):
        """Return the adjoint operator.

        The laplacian is self-adjoint, so this returns ``self``.
