def index_bgen(fn, legacy=False):
    """Indexes a BGEN file.

    Args:
        fn (str): The name of the BGEN file.

    """
    logger.info("Indexing {} (BGEN) using 'bgenix'{}".format(
        fn, " (legacy mode)" if legacy else "",
    ))
    command = ["bgenix", "-g", fn, "-index"]
    if legacy:
        command.append("-with-rowid")
    try:
        logger.info("Executing '{}'".format(" ".join(command)))
        subprocess.Popen(command).communicate()
    except FileNotFoundError:
        logger.error("Cannot find 'bgenix', impossible to index {}".format(fn))
        sys.exit(1)
    logger.info("Index generated")

def has_current_path(self, path, **kwargs):
        """
        Checks if the page has the given path.

        Args:
            path (str | RegexObject): The string or regex that the current "path" should match.
            **kwargs: Arbitrary keyword arguments for :class:`CurrentPathQuery`.

        Returns:
            bool: Whether it matches.
        """

        try:
            return self.assert_current_path(path, **kwargs)
        except ExpectationNotMet:
            return False

def autoBehavior(self, cascade=False):
        """
        Set behavior if name is in self.parentBehavior.knownChildren.

        If cascade is True, unset behavior and parentBehavior for all
        descendants, then recalculate behavior and parentBehavior.
        """
        parentBehavior = self.parentBehavior
        if parentBehavior is not None:
            knownChildTup = parentBehavior.knownChildren.get(self.name, None)
            if knownChildTup is not None:
                behavior = getBehavior(self.name, knownChildTup[2])
                if behavior is not None:
                    self.setBehavior(behavior, cascade)
                    if isinstance(self, ContentLine) and self.encoded:
                        self.behavior.decode(self)
            elif isinstance(self, ContentLine):
                self.behavior = parentBehavior.defaultBehavior
                if self.encoded and self.behavior:
                    self.behavior.decode(self)

def load_value_from_schema(v):
    """
    Load a value from a schema defined string.
    """
    x = urllib.parse.urlparse(v)

    if x.scheme.lower() == 'decimal':
        v = Decimal(x.netloc)
    elif x.scheme.lower() in ['int', 'integer']:
        v = int(x.netloc)
    elif x.scheme.lower() == 'float':
        v = float(x.netloc)
    elif x.scheme.lower() in ['s', 'str', 'string']:
        v = str(x.netloc)
    elif x.scheme.lower() in ['u', 'unicode']:
        v = six.u(x.netloc)
    elif x.scheme.lower() == 'email':
        v = six.u(x.netloc)
    elif x.scheme.lower() == 'bool':
        v = bool(x.netloc)
    elif x.scheme.lower() in ['b', 'bytes']:
        v = six.b(x.netloc)
    elif x.scheme.lower() in ['ts.iso8601', 'timestamp.iso8601']:
        v = MayaDT.from_iso8601(x.netloc).datetime()
    elif x.scheme.lower() in ['ts.rfc2822', 'timestamp.rfc2822']:
        v = MayaDT.from_rfc2822(x.netloc).datetime()
    elif x.scheme.lower() in ['ts.rfc3339', 'timestamp.rfx3339']:
        v = MayaDT.from_rfc3339(x.netloc).datetime()
    elif x.scheme.lower() in ['ts', 'timestamp']:
        v = maya.parse(x.netloc).datetime()
    elif x.scheme.lower() == 'date':
        v = datetime.date.fromtimestamp(float(x.netloc))
    elif x.scheme.lower() == 'time':
        v = time.gmtime(float(x.netloc))
    else:
        v = None

    return v

def convert_to_wav(files):
    '''Converts files to a format that pocketsphinx can deal wtih (16khz mono 16bit wav)'''
    converted = []
    for f in files:
        new_name = f + '.temp.wav'
        print(new_name)
        if (os.path.exists(f + '.transcription.txt') is False) and (os.path.exists(new_name) is False):
            subprocess.call(['ffmpeg', '-y', '-i', f, '-acodec', 'pcm_s16le', '-ac', '1', '-ar', '16000', new_name])
        converted.append(new_name)
    return converted

def handle_stream(plugin, streams, stream_name):
    """Decides what to do with the selected stream.

    Depending on arguments it can be one of these:
     - Output internal command-line
     - Output JSON represenation
     - Continuously output the stream over HTTP
     - Output stream data to selected output

    """

    stream_name = resolve_stream_name(streams, stream_name)
    stream = streams[stream_name]

    # Print internal command-line if this stream
    # uses a subprocess.
    if args.subprocess_cmdline:
        if isinstance(stream, StreamProcess):
            try:
                cmdline = stream.cmdline()
            except StreamError as err:
                console.exit("{0}", err)

            console.msg("{0}", cmdline)
        else:
            console.exit("The stream specified cannot be translated to a command")

    # Print JSON representation of the stream
    elif console.json:
        console.msg_json(stream)

    elif args.stream_url:
        try:
            console.msg("{0}", stream.to_url())
        except TypeError:
            console.exit("The stream specified cannot be translated to a URL")

    # Output the stream
    else:
        # Find any streams with a '_alt' suffix and attempt
        # to use these in case the main stream is not usable.
        alt_streams = list(filter(lambda k: stream_name + "_alt" in k,
                                  sorted(streams.keys())))
        file_output = args.output or args.stdout

        for stream_name in [stream_name] + alt_streams:
            stream = streams[stream_name]
            stream_type = type(stream).shortname()

            if stream_type in args.player_passthrough and not file_output:
                log.info("Opening stream: {0} ({1})", stream_name,
                         stream_type)
                success = output_stream_passthrough(plugin, stream)
            elif args.player_external_http:
                return output_stream_http(plugin, streams, external=True,
                                          port=args.player_external_http_port)
            elif args.player_continuous_http and not file_output:
                return output_stream_http(plugin, streams)
            else:
                log.info("Opening stream: {0} ({1})", stream_name,
                         stream_type)

                success = output_stream(plugin, stream)

            if success:
                break

def simulate_experiment(self, modelparams, expparams, repeat=1, split_by_modelparams=True):
        """
        Simulates the underlying (serial) model using the parallel 
        engines. Returns what the serial model would return, see
        :attr:`~Simulatable.simulate_experiment`

        :param bool split_by_modelparams: If ``True``, splits up
            ``modelparams`` into `n_engines` chunks and distributes 
            across engines. If ``False``, splits up ``expparams``.
        """
        # By calling the superclass implementation, we can consolidate
        # simulation counting there.
        super(DirectViewParallelizedModel, self).simulate_experiment(modelparams, expparams, repeat=repeat)

        if self._dv is None:
                raise RuntimeError(
                    "No direct view provided; this may be because the instance was "
                    "loaded from a pickle or NumPy saved array without providing a "
                    "new direct view."
                )

        # Need to decorate with interactive to overcome namespace issues with
        # remote engines.
        @interactive
        def serial_simulator(sm, mps, eps, r):
            return sm.simulate_experiment(mps, eps, repeat=r)

        if split_by_modelparams:
            # If there's less models than some threshold, just use the serial model.
            # By default, we'll set that threshold to be the number of engines * 10.
            if modelparams.shape[0] <= self._serial_threshold:
                return self.underlying_model.simulate_experiment(modelparams, expparams, repeat=repeat)

            # The trick is that serial_likelihood will be pickled, so we need to be
            # careful about closures.
            os = self._dv.map_sync(
                serial_simulator,
                [self.underlying_model] * self.n_engines,
                np.array_split(modelparams, self.n_engines, axis=0),
                [expparams] * self.n_engines,
                [repeat] * self.n_engines
            )

            return np.concatenate(os, axis=0)

        else:
            # If there's less models than some threshold, just use the serial model.
            # By default, we'll set that threshold to be the number of engines * 10.
            if expparams.shape[0] <= self._serial_threshold:
                return self.underlying_model.simulate_experiment(modelparams, expparams, repeat=repeat)

            # The trick is that serial_likelihood will be pickled, so we need to be
            # careful about closures.
            os = self._dv.map_sync(
                serial_simulator,
                [self.underlying_model] * self.n_engines,
                [modelparams] * self.n_engines,
                np.array_split(expparams, self.n_engines, axis=0),
                [repeat] * self.n_engines
            )

            return np.concatenate(os, axis=1)

def mdaZeros(shap, dtype=numpy.float, mask=None):
    """
    Zero constructor for masked distributed array
    @param shap the shape of the array
    @param dtype the numpy data type
    @param mask mask array (or None if all data elements are valid)
    """
    res = MaskedDistArray(shap, dtype)
    res[:] = 0
    res.mask = mask
    return res

